mapper.select:

where p.user_id = #{userId}
  and p.group_id = #{groupId}
  and p.status = 'ACTIVE'
  and p.expires_at > now()
order by p.expires_at desc, p.id desc
limit 1


where p.id = #{packageId}
  and p.user_id = #{userId}
  and p.status <> 'DELETED'
limit 1


where p.user_id = #{userId}
  and p.group_id = #{groupId}
  and p.status = 'ACTIVE'
  and p.expires_at > now()
order by p.id asc
limit 1


where p.user_id = #{userId}
  and p.group_id = #{groupId}
  and p.status <> 'DELETED'
order by p.expires_at desc, p.id desc
limit 1

select coalesce(sum(l.user_amount), 0)
from request_logs l
join user_model_packages p on p.id = l.user_package_id
where l.user_id = #{userId}
  and p.group_id = #{groupId}
  and l.request_date between #{startDate} and #{endDate}

select coalesce(sum(user_amount), 0)
from request_logs
where user_package_id = #{packageId}
  and request_date between #{startDate} and #{endDate}

select coalesce(sum(user_amount), 0)
from request_logs
where user_package_id = #{packageId}
